LLMResponse(content="from typing import Any


def filter_data(data: list, field: str, value: Any) -> list:
    return [item for item in data if item.get(field) == value]


def sort_data(data: list, key: str, reverse: bool = False) -> list:
    return sorted(data, key=lambda x: x.get(key), reverse=reverse)


def group_data(data: list, field: str) -> dict:
    groups = {}
    for item in data:
        k = item.get(field)
        groups.setdefault(k, []).append(item)
    return groups


def aggregate_data(data: list, field: str, func: str = 'sum') -> Any:
    values = [item.get(field, 0) for item in data]
    if func == 'sum':
        return sum(values)
    if func == 'avg':
        return sum(values) / len(values) if values else 0
    if func == 'min':
        return min(values) if values else None
    if func == 'max':
        return max(values) if values else None
    raise ValueError(f'Unknown aggregation function: {func}')


class DataProcessor:
    def __init__(self, data: list):
        self.data = data

    def filter(self, field: str, value: Any) -> list:
